	var wg sync.WaitGroup
	// Имитируем параллельную обработку 5 HTTP-запросов
	for i := 1; i <= 5; i++ {
		wg.Add(1)
		go func(reqID int) {
			defer wg.Done()
			inst := pool.Acquire()
			defer pool.Release(inst)

			res := inst.Execute(fmt.Sprintf("req-%d", reqID))
			fmt.Println(res)
		}(i)
	}
	wg.Wait()
	time.Sleep(10 * time.Millisecond)
}

